    (F : bvmap 5 word) (fc : bv 32) (m : mem),
  mem_inv asegs m -> a0 = Z_to_bv 64 AGOT_FSTLS -> tp = Z_to_bv 64 ATP ->
  rw_cells asegs m AGOT_FSTLS [C8 (wz 1); C8 (wz 0xfffffffffffff800)] ->
  rw_cells asegs m AMUSL_DTV [C8 (wz 0x65d4d8)] ->
